"""Informe local de demanda base normalizada; no publicación de microdatos."""
from pathlib import Path
import calendar
import json
import pandas as pd


def table(d,cols=None):
    return '<div class="scroll">'+(d[cols] if cols else d).to_html(index=False,na_rep='No estimable / faltante',float_format=lambda x:f'{x:,.3f}',border=0,escape=True)+'</div>'


def chart(out,summary):
    import matplotlib
    matplotlib.use('Agg')
    import matplotlib.pyplot as plt
    labels={'PRIVADOS_COMPATIBLES':'Privados compatibles\nVL+moto+bicicleta; no VL estricto','CAM':'Carga\nvehículos de carga','PEATON':'Peatones\npersonas; no pasajeros totales'}
    fig,axes=plt.subplots(1,3,figsize=(13,4.4));colors=['#a6c8c4','#237f80','#143f54']
    for ax,(seg,label) in zip(axes,labels.items()):
        d=summary[summary.version.eq('B')&summary.segmento.eq(seg)].set_index('escenario')
        vals=[d.loc[s,'flujo_fisico_anual'] for s in ['conservador','central','alto']]
        ax.bar(['Conserv.','Central','Alto'],vals,color=colors)
        ax.set_title(label,fontsize=10);ax.set_ylabel('Unidades de la clase / año normalizado')
        ax.ticklabel_format(axis='y',style='plain');ax.spines[['top','right']].set_visible(False)
    fig.suptitle('ARISTO: escenarios de exposición y proxy invernal, ambos sentidos',fontsize=12)
    fig.text(.5,.01,'No son intervalos estadísticos ni tráfico anual medido. No sumar las tres unidades.',ha='center',fontsize=9)
    fig.tight_layout(rect=(0,.04,1,.92));fig.savefig(out/'escenarios_lacustres.svg');plt.close(fig)


def report(out,base,result,summary,cz,ab,wide):
    chart(out,summary)
    sources=json.loads((base/'lacustre_temporal/final/fuentes_y_decisiones.json').read_text())
    compatibility=json.loads((base/'compatibilidad/resultados/resumen_compatibilidad.json').read_text())
    css='''body{font:16px/1.6 system-ui,sans-serif;color:#213e44;max-width:1240px;margin:auto;padding:28px}h1{line-height:1.2}h2{margin-top:38px;border-bottom:2px solid #c3d8d5}.box{padding:20px;background:#eaf3ef;border-left:6px solid #257d7d}.warn{padding:18px;background:#fff0d7}.scroll{overflow:auto}table{border-collapse:collapse;width:100%;font-size:12px;margin:20px 0}td,th{padding:8px;border:1px solid #cbdad6;text-align:left;vertical-align:top;min-width:90px}th{background:#225d65;color:white}a{color:#086d8c}li{margin:8px 0}pre{white-space:pre-wrap;background:#edf3f0;padding:15px}img{max-width:100%}small{color:#536e72}@media print{body{font-size:11px}.scroll{overflow:visible}table{font-size:8px}}'''
    s='<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Etapa2 — demanda anual base Bahía Jara–Levicán</title><style>'+css+'</style><body>'
    s+='<h1>Demanda anual de referencia: ARISTO y CITRA</h1><p>Etapa 2 · Bahía Jara–Levicán · 29 de octubre de 2026 · Entrega local reservada</p>'
    s+='''<div class="box"><strong>Resultado: existe una base anual condicionada utilizable por bloques, con faltantes explícitos; no un mercado total observado.</strong> ARISTO permite escenarios anuales operacionales para carga, peatones y una vista de privados compatibles. CITRA permite escenarios anuales de ventanas de 12h para parte de sus OD; el total de 24h y el mercado terrestre no observado permanecen desconocidos. Las dos fuentes no se suman. Puede avanzarse con proyecciones por bloques y costos generalizados; una captación del mercado total exige resolver o escenificar los impedimentos de cobertura.</div>'''
    s+='''<ul><li><a href="01_lacustre_anual_A_B.xlsx">Matriz lacustre anual, versiones A/B, temporadas y meses</a>.</li><li><a href="02_terrestre_anual_parcial.xlsx">CITRA: anualización parcial de ventanas12h y contrastes</a>.</li><li><a href="03_base_unificada.xlsx">Base unificada con bloques independientes y faltantes</a>.</li><li><a href="04_supuestos_balances_extranjeros.xlsx">Supuestos, factores, balances, incertidumbre y extranjeros</a>.</li><li><a href="validacion.json">Validaciones</a> · <a href="manifest_integridad.json">Manifiesto de fuentes y resultados</a>.</li></ul>
<h2>1. Qué significa «anual» en esta entrega</h2><p>Se usa el calendario de 2026, 365 días, como <strong>año normalizado de referencia sin crecimiento</strong>. No se reconstruye el tráfico efectivamente realizado durante 2026. ARISTO incluye primavera2025 y campañas2026; CITRA mide jornadas de verano/otoño2026. La conversión anual implica representatividad temporal y, en la barcaza, cumplimiento de una programación ordinaria que no está certificada por bitácoras.</p><p>Todos los valores anuales son cálculos o escenarios. «Observado asignado» identifica el origen del perfil OD de una cantidad física medida; no convierte la cifra anual resultante en un conteo anual observado. OD imputado y proxy temporal son dimensiones distintas y se conservan por separado.</p>
<h2>2. Temporadas y doce meses</h2><p>Se emplean tres perfiles fuente ARISTO: primavera, verano y Normal de mayo. El calendario mantiene cuatro estaciones, pero invierno toma Normal como proxy autorizado. CITRA carece de primavera; su escenario anual utiliza otoño como proxy de primavera e invierno exclusivamente dentro de sus propios OD cubiertos. No utiliza distribución OD de usuarios del ferry.</p>'''
    calendarrows=[]
    for month in range(1,13):
        season='Verano' if month in [12,1,2] else 'Otoño' if month in [3,4,5] else 'Invierno' if month in [6,7,8] else 'Primavera'
        calendarrows.append(dict(mes=month,dias=calendar.monthrange(2026,month)[1],temporada_destino=season,
            perfil_ARISTO='Normal mayo (proxy invernal)' if season=='Invierno' else 'Normal mayo' if season=='Otoño' else season,
            perfil_CITRA='Verano' if season=='Verano' else 'Otoño'+(' (proxy)' if season in ['Invierno','Primavera'] else ''),
            frecuencia_ordinaria_semana_sentido=11 if month in [12,1,2,3,4] else 8))
    s+=table(pd.DataFrame(calendarrows))
    s+='''<p>Las observaciones no se suman como días distintos del año. Primero se obtiene un perfil por exposición, y luego se aplica al calendario indicado. Marzo/abril usan composición Normal, pero frecuencia alta; mayo usa frecuencia baja. Eso también es una transferencia estacional explícita. Los perfiles de primavera no corresponden a marzo/abril ni se completa invierno como si se hubiera encuestado.</p>
<h2>3. ARISTO A/B: conservar F, distinguir distribución</h2><p><strong>A, referencia observada:</strong> conserva la asignación de encuestas de la misma fecha, sentido y clase; retiene todo F sin perfil en residual. Los extremos internacionales genéricos se etiquetan EXTERNO_NO_ESPECIFICADO, sin inventar zona.</p><p><strong>B, referencia completada:</strong> conserva exactamente los mismos F y solo transfiere distribución de otro día comparable dentro de campaña/sentido/clase. El caso aplicado son cinco camiones del 1febrero PuertoIbáñez→ChileChico, con perfil del27enero basado en dos entrevistas. La sensibilidad A/B suprime esa transferencia, no cambia el flujo físico. Ningún peatón usa perfil de vehículo, ni un usuario terrestre recibe proporciones de ARISTO.</p><p>En la muestra medida de carga ambas versiones tienen29vehículos: A asigna22 y conserva7residuales; B agrega5ODimputados y conserva2residuales. El escaso Ndonante es una limitación, no una precisión estadística. Los120peatones de verano en sentido PuertoIbáñez→ChileChico siguen sin perfil; tampoco se fuerzan motos/bicicletas sin donantes. Todos los balances por fecha, sentido y clase se conservan.</p>
<h2>4. Exposición lacustre y escenarios</h2><p>La unidad mínima del InformeARISTO §2.2.6 es semanal, a partir de flujo medio por servicio. El Excel no identifica inequívocamente el zarpe de cada fila. Por eso se usa evidencia de programación y se declara la hipótesis de cobertura de esas operaciones: <code>Q_mes = ΣF_muestra / operaciones_programadas_muestra × frecuencia_ordinaria_semana / 7 × días_mes</code>. La composición OD y los residuales se multiplican por el mismo coeficiente.</p>'''
    exp=pd.read_csv(base/'lacustre_temporal/final/exposicion_por_campana_sentido.csv')
    s+=table(exp)
    s+='''<p>Primavera: dos horarios por sentido en la planificación del08noviembre, tabla78. Verano: la tabla38 programa una salida el martes y dos el domingo; para PuertoIbáñez→ChileChico se usan tres operaciones entre27enero y1febrero, aunque haya solo dos filas de conteo. ChileChico→PuertoIbáñez tiene dos operaciones programadas el1febrero. Normal10mayo: <a href="https://www.navieraustral.cl/itinerario-semanal-de-barcazas-04-19-mayo/">Naviera Austral publica una salida por sentido</a>. Son programas, no prueba de salidas efectivas.</p><p>La frecuencia ordinaria11dic–abr/8may–nov por sentido fue confirmada previamente por el usuario. El itinerario Naviera de04–10mayo publica nueve tramos por sentido sin clasificar ordinario/especial: se conserva como contraste, no se cambia automáticamente la frecuencia ordinaria ni se inventa una cuota de carga peligrosa. No existe bitácora o boletaje completo que certifique la exposición efectiva ni permita introducir un porcentaje de cancelaciones meteorológicas.</p>
<ul><li><strong>Central:</strong> operaciones programadas de la muestra y frecuencia ordinaria11/8, cumplimiento supuesto; invierno=Normal de mayo.</li><li><strong>Conservador:</strong> misma exposición, con reducción invernal externa por clase compatible. PNC2024 PC64/rama1 entrega la razón Invierno/Primavera de carga y de privados agregados. Se aplica como stress sobre mayo, <em>no como razón invierno/otoño lacustre observada</em>. Peatones no reciben un factor vial.</li><li><strong>Alto:</strong> mantiene invierno=Normal y contrasta dos operaciones en veranoPuertoIbáñez→ChileChico, frente a las tres programadas del central. Los demás estratos no se incrementan sin evidencia.</li></ul><p>La lectura «total de día muestreado × días del año» se entrega en la tarea temporal como contraste, no como central: los días medidos con dos salidas no representan automáticamente un calendario de8/7salidas diarias. La lectura de una fila como un zarpe tampoco se aplica sin rotularla. Los escenarios son hipótesis de exposición y estacionalidad, no intervalos estadísticos ni toda la incertidumbre posible. No calibran suspensiones o carenas efectivas de2026.</p>
<h3>Resultados lacustres por unidad compatible</h3><p>Ambos sentidos sumados dentro de cada clase y escenario; <strong>no sumar las clases entre sí</strong>. La vista PRIVADOS_COMPATIBLES combina VL+moto+bicicleta de primavera/verano con VP de Normal; nunca se suma otra vez con sus componentes ni se denomina VL estricto.</p>'''
    selected=summary[summary.version.eq('B')&summary.segmento.isin(['PRIVADOS_COMPATIBLES','CAM','PEATON'])]
    s+=table(selected,['version','escenario','segmento','flujo_fisico_anual','observado_OD_anualizado','imputado_OD_anualizado','residual_anualizado','fraccion_imputada_OD','fraccion_residual'])
    s+='<img src="escenarios_lacustres.svg" alt="Escenarios anuales separados por unidad de clase">'
    s+='''<p>La proporción imputada se refiere a distribución OD; la expansión temporal afecta todos los componentes. Una cantidad residual anual también es estimada temporalmente a partir de un embarque medido, no un aforo anual. Las matrices incluyen las versiones A y B por separado.</p><div class="warn"><strong>Clases estrictas sin año completo:</strong> VL, motos y bicicletas no tienen Normal desagregada compatible en la matriz OD; VP solo tiene el perfil Normal. Sus columnas anuales estrictas permanecen faltantes y se muestran aportes parciales. La vista alternativa de privados compatibles permite una referencia anual agregada sin repartir VP a subclases artificialmente.</div>
<h2>5. CITRA: anualización de la parte cubierta</h2>'''
    s+=f'''<p>Hay {result['CITRA_zonas_anual12h_estimables_por_escenario']} combinaciones zonales/clase y {result['CITRA_localidades_anual12h_estimables_por_escenario']} pares detallados/clase con dos campañas que admiten un escenario de365días de <strong>ventanas08–20</strong>. El resto conserva aportes de meses representados y anual faltante. La cifra anual de24h es faltante en todas las celdas.</p>'''
    s+='''<p><code>Q_anual_12h = 90×perfil_verano + 92×perfil_otoño + 92×proxy_invierno + 91×proxy_primavera</code>. Central: proxies desde el propio otoñoCITRA. Conservador: invierno multiplicado por razón PNC2024 Invierno/Primavera del corredor aproximado, por VL/CAM; primavera sigue como proxy otoñal. Alto=Central porque no hay incremento superior cuantitativo respaldado sin cambiar pantalla o introducir porcentajes.</p><p>PNCPC63/rama2(Ruta7,BifMurta) yPC64/rama1(Ruta265,MallínGrande–Guadal) contrastan la forma estacional, sin equivalencia exacta de ubicación, sentido, ventana o OD. Son conteos históricos publicados con su propia expansión; sus razones no validan un factor12→24. Los coeficientes genéricos MOP y perfiles urbanos no reemplazan un aforo interurbano24h compatible. Tampoco se certifica representatividad de fines de semana con jornadas laborales escasas.</p>'''
    s+=table(cz[cz.escenario.eq('Central')],['zona_origen','zona_destino','segmento','demanda_anual_ventana12h','demanda_anual24h','dias_con_campana_propia','dias_proxy_invierno_primavera','estado'])
    s+='''<p>Se conserva la pantalla elegida en Etapa1 y las estimaciones alternativas. En ChileChico→RíoIbáñez, veranoVL, los controles comparables difieren3,73 frente25,07vehículos/12h; esa incertidumbre no desaparece por multiplicar días. Se entrega aparte y no se elige el mayor flujo ni se promedian controles para ocultarla. La distribución de localidades dentro de una zona puede cambiar entre campañas: el perfil zonal directo y el agregado de localidades comunes tienen distinto soporte y no se fuerza su igualdad.</p><p><strong>No se completó la magnitud terrestre faltante:</strong> no se usan proporciones OD lacustres ni se extrapola la fracciónCITRA a todo el corredor. Un aporte parcial no es un límite estadístico del mercado total; el componente no observado sigue desconocido.</p>
<h2>6. Integración, doble conteo y desconocidos</h2><p>La base larga distingue bloque lacustre/terrestre, fuente, versiónOD, escenario, vista, zona, detalle, segmento, unidad y exposición. La tabla porOD presenta ambas referencias con faltantes explícitos y total_combinado nulo. Coincidencia de OD no implica compatibilidad temporal.</p><p>La auditoríaCITRA previa conserva109entrevistas elegibles sin alternativa ferry compatible en las trayectorias de referencia. Eso respalda la separación de corredores mediante inferencia topológica, pero no acredita deduplicación individual entre consultoras ni certeza del itinerario completo. No se añaden pantallas comunes a accesos del ferry y no se suman aforos en serie.</p><p>La unión de Etapa1 contiene67claves OD/campaña/clase, seis con flujo en ambas fuentes. Es una comparación de cobertura, no un total de demanda. El faltante de una fuente no se transforma en cero ni se rellena mediante la otra. VP no se homologa automáticamente a VL; los pasajeros de bus no reciben factores vehiculares.</p>
<h2>7. Extranjeros: variables listas, sin beneficios por divisas</h2><p>Se mantienen nacionalidad declarada, patente y OD internacional como tres indicadores superpuestos. La nacionalidad peatonal no es residencia y la patente no es nacionalidad de ocupantes. Se conservaron5declaraciones extranjeras,10patentes extranjeras y13ODinternacionales en las264respuestasARISTO, sin sumarlos como personas distintas.</p><p>El Excel de factores incluye aportes anuales por categoría de indicador en estratos compatibles y su denominador físico de clase. La fracción asociada se refiere a perfil conocido, no a extranjeros totales. Se calcula también la parte sin caracterización, por ejemplo ante ausencia de entrevistas peatonales en una dirección estival. Los estados desconocidos permanecen explícitos. La versiónB solo imputa OD: no hereda nacionalidad, patente o residencia de los donantes. No se calcularon divisas, bienestar o beneficios sociales.</p>
<h2>8. Incertidumbres materiales y decisión de avance</h2><ul><li><strong>Exposición y operación lacustre:</strong> faltan zarpes efectivamente realizados y vínculo fila–operación. El central es el mejor escenario programado disponible, condicionado a cobertura de las operaciones planificadas y al programa11/8.</li><li><strong>Invierno:</strong> otoño como proxy está autorizado; no hay serie propia suficiente para estimar relación invierno/otoño del ferry. La reducción PNC es solo un stress externo y no informa peatones.</li><li><strong>Representatividad OD:</strong> primaveraARISTO presenta N&gt;F, sin identificar vehículo; no respuesta y unidad de selección no certificadas. Imputación de carga usa Ndonante2.</li><li><strong>CITRA:</strong> falta exposición nocturna, representación de tipos de día, parte del mercado y homogeneidad del soporte detallado. La discrepancia entre controles debe conservarse.</li><li><strong>Unidades:</strong> no hay VL anual estricto desdeVPsin desagregación; peatones no son pasajeros totales. Hay flujos residuales geográficos y sin perfil.</li></ul>
<p><strong>Podemos avanzar</strong> con proyecciones propias por bloque/segmento compatible y con costos generalizados, utilizando esta base como escenarios condicionados sin crecimiento ya incorporado. La captación puede estudiarse para los mercados efectivamente cubiertos, manteniendo sensibilidad de pantalla y exposición. <strong>No está respaldada todavía una captación única del mercado total ni cuotas entre ferry y tierra basadas en sumar estos anuales.</strong> Para ello hacen falta operación efectiva/denominador lacustre, factores horarios y cobertura terrestre, o escenarios posteriores explícitos del mercado desconocido. No se inicia ese trabajo en esta entrega.</p>
<h2>9. Fuentes, referencias y reproducción</h2><ol><li>ARISTO, <em>Informe Final, Análisis demanda transporte interregional LosLagos,Aysén yMagallanes</em>: §§2.2.5–2.2.6 pp.6–7 (embarques/expansión semanal); tabla38 pp.111–112 (programación); tabla78 p.173 (plan primavera); tablas107 pp.187–188,138 p.207,169 p.223 (conteos).</li><li>OriginalesARISTO Cap6/BBDD EOD/Base de datos agregada.xlsx y Consolidado Flujos.xlsx; se reutiliza etapa1_lacustre_aristo_20261029/resultados/entrega_final, sin volver a leer todas las encuestas. VersionesA/B y factores de esta entrega registran sus hashes.</li><li><a href="https://www.navieraustral.cl/itinerario-semanal-de-barcazas-04-19-mayo/">NavieraAustral, programación04–19mayo2026</a>, secciónLaTehuelche: salida del10mayo y contraste semanal. Programa referencial, no bitácora.</li><li>Vialidad, PNC2024 y contraste histórico2018/2022, archivo original Cap3/Flujosvehiculares/Flujos_Vehiculares_PNC_2024-2022-2020-2018-2016-2014.xlsx, hojaBBDD, PC63/rama2 yPC64/rama1. Filas/categorías enPNC_fuente_PC63_PC64.csv. No se usa2020pandemia para el stress central.</li><li>CITRA, EOD verano/otoño y aforos de sección originales; entrega aprobada etapa1_terrestre_citra/resultados/cierre_final_04. Referencias previas: informesCITRA1/2c/3c y sus anexos. Perfiles urbanos y coeficientes MOPgenéricos contrastados, no transferidos como prueba de24h.</li><li>Fuentes históricas ARISTO/Naviera/Vialidad se revisaron para exposición y forma estacional. Cap3 no contiene una serie mensual propia de este ferry que permita calibrar invierno/otoño; las series aéreas no se usaron como demanda lacustre.</li></ol>
<p>Cuatro roles separados: A asignación/residual; B exposición/calendario; C anualizaciónterrestre/PNC; D compatibilidad. Las tareas independientes se ejecutaron en paralelo con un máximo de tres subagentes activos. No se reconstruyó red, geocodificó ni ejecutó Etapas07–13.</p>
<pre>python etapa2_demanda_anual_20261029/integracion/consolidar_etapa2.py \\
  --anexos . \\
  --etapa2 etapa2_demanda_anual_20261029 \\
  --salida /tmp/ETAPA2_NUEVA_ENTREGA</pre>
<p>El paquete contiene scripts de las cuatro tareas, pruebas y comandos para regenerar desde las cachés aprobadas. Se exige carpeta nueva, se controla espacio antes de escribir y se verifican los hashes de ambas entregas previas. La publicación aGitHub quedó cancelada; no se publican microdatos. Los únicos archivos retirados del intento de subida fueron sus temporales, no las entregas del proyecto.</p>'''
    s+=f'<p><small>Integración: {result["segundos_integracion"]}s; {len(result["verificaciones"])} comprobaciones correctas. Originales y referencias aprobadas intactos. Los gráficos y tablas son escenarios de incertidumbre de la base, no crecimiento, captación o inducción.</small></p></body></html>'
    (out/'informe_etapa2.html').write_text(s,encoding='utf-8')
